def recommend_start(computer, programming, networking, correct, total):
    """Choose a starting level. Ethics, terminology, labs, and the exam stay required."""
    ratio = 0 if not total else correct / total
    start = 0
    if computer in {"some", "comfortable"} and ratio >= 0.4:
        start = 2
    if computer == "comfortable" and networking in {"some", "comfortable"} and ratio >= 0.6:
        start = 4
    if (
        computer == "comfortable"
        and programming == "comfortable"
        and networking == "comfortable"
        and ratio >= 0.75
    ):
        start = 6
    if programming == "none":
        start = min(start, 4)
    if networking == "none":
        start = min(start, 2)
    if computer == "none":
        start = 0
    return start


def department_curriculum(slug, name, overview, topics):
    topics = list(topics or [])
    first = topics[0] if topics else name
    third = max(1, len(topics) // 3)
    return {
        "basics": f"{overview} If {name} is new to you, start with ZeroTrace Foundations. You do not need to know this department's tools yet.",
        "terminology": topics[:8],
        "prerequisites": _department_prerequisites(slug),
        "beginner": f"In the beginner introduction, learn what {first} means in ordinary language and how it supports confidentiality, integrity, or availability. Stay with the definitions before any lab.",
        "first_practical": {
            "objective": f"Explain {first} without using a live target.",
            "steps": [
                f"Read the overview of {name}.",
                f"Write, in your own words, what {first} is for.",
                "List two Foundations topics you would review before an advanced lab.",
                "Do not scan, sign in to, or change a system this sheet does not name.",
            ],
            "expected": "A short note in your own words.",
            "questions": [f"Which people or systems would be harmed if {first} failed?"],
            "completion": "The note defines the idea and names a Foundations topic.",
            "cleanup": "Keep the note in your own folder. Do not include someone else's data.",
        },
        "intermediate": topics[third: third * 2] or topics,
        "advanced": topics[third * 2:] or topics,
        "assessment": "A graded practical assessment is published with the department course, after the beginner note and the Foundations certificate or an accepted placement. It asks you to explain the basics and record observations. It is not published as an empty course.",
    }


